function handleRenewalFailure(orderId: string, reason: string): void {
  // Called by the billing worker when a subscription renewal is declined.
  // The customer keeps access during the grace period; we just notify them.

  const order = orders.get(orderId);
  if (!order) {
    logger.warn(`renewal failure for unknown order ${orderId}`);
    return;
  }

  // Don't send a second email if the customer already updated their card
  // while the retry job was still running.
  if (order.paymentStatus === 'updated_recently') {
    return;
  }

  notifications.sendRenewalFailedEmail({
    recipient: order.customerEmail,
    gracePeriodDays: 7,
    reason,
  });
}
